import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-register',
  templateUrl: './register.component.html'
})
export class RegisterComponent {
  form: FormGroup;
  loading = false;
  error = '';
  success = false;

  constructor(
    private fb: FormBuilder,
    private auth: AuthService,
    private router: Router
  ) {
    this.form = this.fb.group({
      login: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(6)]],
      nom: ['', Validators.required],
      prenom: ['', Validators.required],
      tel: ['']
    });
  }

  onSubmit(): void {
    if (this.form.invalid) return;
    this.loading = true;
    this.error = '';
    this.auth.register(this.form.value).subscribe({
      next: () => {
        this.loading = false;
        this.success = true;
        setTimeout(() => this.router.navigate(['/login']), 2000);
      },
      error: (err) => {
        this.loading = false;
        this.error = err.error?.message || 'Erreur lors de l\'inscription';
      }
    });
  }
}
<div class="auth-wrapper">
  <div class="auth-card">
    <div class="logo">
      <i class="bi bi-heart-pulse"></i>
    </div>
    <h2>Inscription</h2>
    <p class="subtitle">Créer un compte collaborateur</p>

    <div *ngIf="error" class="alert alert-danger py-2">{{ error }}</div>
    <div *ngIf="success" class="alert alert-success py-2">
      Compte créé avec succès ! Redirection...
    </div>

    <form [formGroup]="form" (ngSubmit)="onSubmit()" *ngIf="!success">
      <div class="row">
        <div class="col-6 mb-3">
          <label class="form-label">Prénom</label>
          <input type="text" class="form-control" formControlName="prenom">
        </div>
        <div class="col-6 mb-3">
          <label class="form-label">Nom</label>
          <input type="text" class="form-control" formControlName="nom">
        </div>
      </div>
      <div class="mb-3">
        <label class="form-label">Email</label>
        <input type="email" class="form-control" formControlName="login">
      </div>
      <div class="mb-3">
        <label class="form-label">Téléphone</label>
        <input type="text" class="form-control" formControlName="tel">
      </div>
      <div class="mb-3">
        <label class="form-label">Mot de passe</label>
        <input type="password" class="form-control" formControlName="password">
        <div class="form-text">Minimum 6 caractères</div>
      </div>
      <button type="submit" class="btn btn-primary w-100 py-2" [disabled]="loading || form.invalid">
        <span *ngIf="loading" class="spinner-border spinner-border-sm me-2"></span>
        S'inscrire
      </button>
    </form>

    <p class="text-center mt-3 mb-0 text-muted" style="font-size:0.9rem;">
      Déjà un compte ?
      <a routerLink="/login" class="fw-semibold">Se connecter</a>
    </p>
  </div>
</div>
